import sys
from collections import defaultdict, deque

input = sys.stdin.readline

def find_min_diff(tree, values, a, b):
    # Perform a BFS to find the simple path between nodes a and b
    queue = deque([a])
    parent = {a: None}
    path = []

    while queue:
        node = queue.popleft()
        path.append(node)
        if node == b:
            break
        for neighbor in tree[node]:
            if neighbor not in parent:
                parent[neighbor] = node
                queue.append(neighbor)

    # Find the minimum absolute difference between any two nodes on the path
    min_diff = float('inf')
    seen = set()
    for node in path:
        if values[node-1] in seen:
            min_diff = min(min_diff, abs(values[node-1] - values[node-1]))
        seen.add(values[node-1])

    return min_diff

def main():
    T = int(input())
